    # The most frequent color is the panel background; uniform lines in
    # other colors act as separators.
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    background = max(freq, key=freq.get)

    row_lines = [r for r in range(h)
                 if len(set(grid[r])) == 1 and grid[r][0] != background]
    col_lines = [c for c in range(w)
                 if len({grid[r][c] for r in range(h)}) == 1
                 and grid[0][c] != background]

    def sections(size, separators):
        parts = []
        start = 0
        for p in sorted(separators):
            if start < p:
                parts.append((start, p))
            start = p + 1
        if start < size:
            parts.append((start, size))
        return parts

    rows = sections(h, row_lines)
    cols = sections(w, col_lines)

    # Find the panel containing the most non-background cells.
    panels = []
